Define `__neg__`. Python calls it for `-obj`. Return a new object instead of changing `self`. `__pos__` and `__abs__` work the same way.

```python
class Temp:
    def __init__(self, value):
        self.value = value

    def __neg__(self):
        return Temp(-self.value)

    def __repr__(self):
        return f"Temp({self.value})"

print(-Temp(5))      # Temp(-5)
print(-(-Temp(5)))   # Temp(5)
